import React, { useState, useEffect } from 'react';
import axios from 'axios'; // ⭐ axios 임포트

const ContentManagementTab = () => {
  const [searchBoard, setSearchBoard] = useState(''); // 사찰정보, 리뷰, 사찰댓글, 리뷰댓글
  const [searchKeyword, setSearchKeyword] = useState('');
  const [searchNickname, setSearchNickname] = useState('');
  const [inactivePosts, setInactivePosts] = useState([]); // 백엔드에서 가져온 실제 데이터
  const [inactiveComments, setInactiveComments] = useState([]); // 백엔드에서 가져온 실제 데이터
  const [loading, setLoading] = useState(false); // 로딩 상태
  const [error, setError] = useState(null); // 에러 상태

  // 페이지네이션을 위한 상태 (필요에 따라 추가)
  const [currentPage, setCurrentPage] = useState(0);
  const [totalPages, setTotalPages] = useState(0);
  const [currentBoardType, setCurrentBoardType] = useState(''); // 현재 조회 중인 게시판 타입

  // API 요청 함수
  const fetchInactiveContents = async (boardType, keyword = '', nickname = '', page = 0) => {
    setLoading(true);
    setError(null);
    setCurrentBoardType(boardType); // 현재 조회 중인 게시판 타입 저장

    try {
      // ⭐ JWT 토큰 가져오기 (실제 구현에 맞춰 수정 필요)
      const token = localStorage.getItem('accessToken'); // 예시: 로컬 스토리지에서 토큰 가져오기
      if (!token) {
        alert('로그인이 필요합니다.');
        setLoading(false);
        return;
      }

      const params = {
        boardType: boardType, // "TEMPLE", "REVIEW", "TEMPLE_COMMENT", "REVIEW_COMMENT"
        keyword: keyword,
        memberUsername: nickname,
        page: page,
        size: 10, // 한 페이지에 10개씩 (필요에 따라 조절)
        sortBy: 'createdAt',
        sortOrder: 'desc',
      };

      const response = await axios.get('/api/admin/contents/inactive', {
        headers: {
          Authorization: `Bearer ${token}`, // JWT 토큰 포함
        },
        params: params,
      });

      console.log('API 응답:', response.data); // 응답 데이터 확인

      if (boardType === 'TEMPLE') {
        setInactivePosts(response.data.temples ? response.data.temples.content : []);
        setTotalPages(response.data.temples ? response.data.temples.totalPages : 0);
      } else if (boardType === 'REVIEW') {
        setInactivePosts(response.data.reviews ? response.data.reviews.content : []);
        setTotalPages(response.data.reviews ? response.data.reviews.totalPages : 0);
      } else if (boardType === 'TEMPLE_COMMENT') {
        setInactiveComments(response.data.templeComments ? response.data.templeComments.content : []);
        setTotalPages(response.data.templeComments ? response.data.templeComments.totalPages : 0);
      } else if (boardType === 'REVIEW_COMMENT') {
        setInactiveComments(response.data.reviewComments ? response.data.reviewComments.content : []);
        setTotalPages(response.data.reviewComments ? response.data.reviewComments.totalPages : 0);
      }

      setCurrentPage(page);

    } catch (err) {
      console.error('비활성화 콘텐츠 조회 실패:', err);
      setError('콘텐츠를 불러오는 데 실패했습니다.');
      setInactivePosts([]); // 에러 발생 시 목록 초기화
      setInactiveComments([]);
      setTotalPages(0);
    } finally {
      setLoading(false);
    }
  };

  // 컴포넌트 마운트 시 초기 데이터 로드 (예: 기본적으로 리뷰 게시글 목록 로드)
  useEffect(() => {
    fetchInactiveContents('REVIEW'); // 초기 로드 시 '리뷰' 게시글 목록을 가져옴
  }, []);

  const handleSearch = (e) => {
    e.preventDefault();
    // searchBoard 값에 따라 실제 백엔드 boardType으로 매핑
    let backendBoardType = '';
    if (searchBoard === '사찰정보') {
      backendBoardType = 'TEMPLE';
    } else if (searchBoard === '리뷰') {
      backendBoardType = 'REVIEW';
    } else if (searchBoard === '사찰댓글') { // 댓글 검색도 추가!
      backendBoardType = 'TEMPLE_COMMENT';
    } else if (searchBoard === '리뷰댓글') { // 댓글 검색도 추가!
      backendBoardType = 'REVIEW_COMMENT';
    } else {
      alert('게시판을 선택해주세요.');
      return;
    }
    fetchInactiveContents(backendBoardType, searchKeyword, searchNickname, 0);
  };

  // 게시글 활성화/삭제
  const handlePostAction = async (postId, actionType, boardType) => {
    const post = inactivePosts.find(p => p.reviewId === postId || p.templeId === postId);
    if (!post) return;

    // ⭐ JWT 토큰 가져오기
    const token = localStorage.getItem('accessToken');
    if (!token) {
      alert('로그인이 필요합니다.');
      return;
    }

    try {
      if (actionType === '활성화') {
        if (boardType === 'TEMPLE') {
          await axios.patch(`/api/temples/${postId}/status`, null, { // null은 RequestBody가 없다는 의미
            params: { isActive: true }, // 쿼리 파라미터로 isActive 전달
            headers: { Authorization: `Bearer ${token}` },
          });
          alert(`사찰 게시글 "${post.templeName}"을 활성화했습니다.`);
        } else if (boardType === 'REVIEW') {
          await axios.patch(`/api/reviews/${postId}/status`, null, {
            params: { isActive: true },
            headers: { Authorization: `Bearer ${token}` },
          });
          alert(`리뷰 게시글 "${post.title}"을 활성화했습니다.`);
        }
      } else if (actionType === '삭제') { // 게시글 삭제 (소프트 삭제)
        if (!window.confirm(`게시글 "${post.title || post.templeName}"을 정말 삭제하시겠습니까? (복구 불가)`)) {
          return;
        }
        if (boardType === 'TEMPLE') {
          await axios.delete(`/api/temples/${postId}`, { // DELETE 요청
            headers: { Authorization: `Bearer ${token}` },
          });
          alert(`사찰 게시글 "${post.templeName}"을 삭제했습니다.`);
        } else if (boardType === 'REVIEW') {
          await axios.patch(`/api/reviews/${postId}/soft-delete`, null, { // PATCH 요청 (소프트 삭제)
            headers: { Authorization: `Bearer ${token}` },
          });
          alert(`리뷰 게시글 "${post.title}"을 삭제했습니다.`);
        }
      }
      // 액션 성공 후 목록 새로고침
      fetchInactiveContents(currentBoardType, searchKeyword, searchNickname, currentPage);

    } catch (err) {
      console.error(`${actionType} 액션 실패:`, err.response ? err.response.data : err.message);
      alert(`${actionType} 실패: ` + (err.response ? err.response.data : err.message));
    }
  };

  // 댓글 활성화/삭제
  const handleCommentAction = async (commentId, actionType, boardType, parentId) => {
    const comment = inactiveComments.find(c => c.reviewCommentId === commentId || c.templeCommentId === commentId);
    if (!comment) return;

    const token = localStorage.getItem('accessToken');
    if (!token) {
      alert('로그인이 필요합니다.');
      return;
    }

    try {
      if (actionType === '활성화') {
        // 백엔드에 댓글 활성화 API가 명시적으로 없는 경우, 여기서는 단순 메시지 출력
        // 만약 백엔드에 isDeleted=false로 변경하는 API가 있다면 해당 API를 호출해야 함.
        alert(`댓글 "${comment.content}" 활성화 기능은 현재 백엔드 API에 구현되지 않았습니다.`);
      } else if (actionType === '삭제') { // 댓글 삭제 (소프트 삭제)
        if (!window.confirm(`댓글 "${comment.content}"을 정말 삭제하시겠습니까? (복구 불가)`)) {
          return;
        }
        if (boardType === 'TEMPLE_COMMENT') {
          await axios.delete(`/api/temples/${comment.templeId}/comments/${commentId}`, { // parentId 사용 (templeId)
            headers: { Authorization: `Bearer ${token}` },
          });
          alert(`사찰 댓글 "${comment.content}"을 삭제했습니다.`);
        } else if (boardType === 'REVIEW_COMMENT') {
          await axios.delete(`/api/reviews/${comment.reviewId}/comments/${commentId}`, { // parentId 사용 (reviewId)
            headers: { Authorization: `Bearer ${token}` },
          });
          alert(`리뷰 댓글 "${comment.content}"을 삭제했습니다.`);
        }
      }
      // 액션 성공 후 목록 새로고침
      fetchInactiveContents(currentBoardType, searchKeyword, searchNickname, currentPage);

    } catch (err) {
      console.error(`${actionType} 액션 실패:`, err.response ? err.response.data : err.message);
      alert(`${actionType} 실패: ` + (err.response ? err.response.data : err.message));
    }
  };

  // 페이지네이션 렌더링
  const renderPagination = () => {
    const pages = [];
    for (let i = 0; i < totalPages; i++) {
      pages.push(
        <button
          key={i}
          className={`page-button ${i === currentPage ? 'active' : ''}`}
          onClick={() => fetchInactiveContents(currentBoardType, searchKeyword, searchNickname, i)}
          disabled={loading}
        >
          {i + 1}
        </button>
      );
    }
    return <div className="pagination">{pages}</div>;
  };


  return (
    <div className="tab-content-section content-management-tab">
      <h3 className="tab-content-title">콘텐츠 관리 🛡️</h3>
      <form onSubmit={handleSearch} className="search-form">
        <select value={searchBoard} onChange={(e) => setSearchBoard(e.target.value)}>
          <option value="">게시판 선택</option>
          <option value="사찰정보">사찰정보</option>
          <option value="리뷰">리뷰</option>
          <option value="사찰댓글">사찰댓글</option> {/* 댓글 검색 옵션 추가 */}
          <option value="리뷰댓글">리뷰댓글</option> {/* 댓글 검색 옵션 추가 */}
        </select>
        <input
          type="text"
          placeholder="검색 키워드 (제목/내용)"
          value={searchKeyword}
          onChange={(e) => setSearchKeyword(e.target.value)}
        />
        <input
          type="text"
          placeholder="작성자 닉네임"
          value={searchNickname}
          onChange={(e) => setSearchNickname(e.target.value)}
        />
        <button type="submit" className="search-button" disabled={loading}>검색</button>
      </form>

      {loading && <p>데이터를 불러오는 중입니다... ⏳</p>}
      {error && <p className="error-message">오류: {error}</p>}

      {/* 게시글 목록 */}
      {['TEMPLE', 'REVIEW'].includes(currentBoardType) && (
        <>
          <h4>비활성화 게시글 목록 ({inactivePosts.length}개)</h4>
          <div className="post-list">
            {inactivePosts.length > 0 ? (
              inactivePosts.map(post => (
                <div key={post.reviewId || post.templeId} className="post-item">
                  <span className="post-title">
                    [{post.boardType === 'TEMPLE' ? '사찰정보' : '리뷰'}] {post.title || post.templeName}
                    {post.memberUsername && ` (작성자: ${post.memberUsername})`} {/* 작성자 닉네임 표시 */}
                  </span>
                  <div>
                    {/* 활성화 버튼: isDeleted가 true이면 비활성화, isActive가 false이면 활성화 가능 */}
                    <button
                      className="action-button"
                      onClick={() => handlePostAction(post.reviewId || post.templeId, '활성화', post.boardType)}
                      disabled={post.isActive === true || post.isDeleted === false} // 이미 활성/삭제되지 않은 경우 비활성화
                    >
                      활성화
                    </button>
                    <button
                      className="action-button delete-button"
                      onClick={() => handlePostAction(post.reviewId || post.templeId, '삭제', post.boardType)}
                      disabled={post.isDeleted === true} // 이미 삭제된 경우 비활성화
                    >
                      삭제
                    </button>
                  </div>
                </div>
              ))
            ) : (
              <p>비활성화된 게시글이 없어요. ✨</p>
            )}
          </div>
        </>
      )}

      {/* 댓글 목록 */}
      {['TEMPLE_COMMENT', 'REVIEW_COMMENT'].includes(currentBoardType) && (
        <>
          <h4 style={{ marginTop: '40px' }}>비활성화 댓글 목록 ({inactiveComments.length}개)</h4>
          <div className="comment-list">
            {inactiveComments.length > 0 ? (
              inactiveComments.map(comment => (
                <div key={comment.reviewCommentId || comment.templeCommentId} className="comment-item">
                  <span className="comment-content">
                    [{comment.boardType === 'TEMPLE' ? '사찰정보' : '리뷰'}] {comment.content}
                    {comment.memberUsername && ` (작성자: ${comment.memberUsername})`} {/* 작성자 닉네임 표시 */}
                  </span>
                  <div>
                    {/* 댓글 활성화는 백엔드 기능에 따라 주석 처리 */}
                    {/*
                    <button
                      className="action-button"
                      onClick={() => handleCommentAction(comment.reviewCommentId || comment.templeCommentId, '활성화', comment.boardType, comment.reviewId || comment.templeId)}
                      disabled={comment.isDeleted === false} // 이미 삭제되지 않은 경우 비활성화
                    >
                      활성화
                    </button>
                    */}
                    <button
                      className="action-button delete-button"
                      onClick={() => handleCommentAction(comment.reviewCommentId || comment.templeCommentId, '삭제', comment.boardType, comment.reviewId || comment.templeId)}
                      disabled={comment.isDeleted === true} // 이미 삭제된 경우 비활성화
                    >
                      삭제
                    </button>
                  </div>
                </div>
              ))
            ) : (
              <p>비활성화된 댓글이 없어요. ✨</p>
            )}
          </div>
        </>
      )}

      {/* 페이지네이션 버튼 */}
      {totalPages > 1 && renderPagination()}
    </div>
  );
};

export default ContentManagementTab;
